<script setup lang="ts">
import type {LabAlgorithm,LabSelection} from '../algorithmLab';
const props=defineProps<{catalog:LabAlgorithm[];modelValue:LabSelection[];mode:string}>();
const emit=defineEmits<{'update:modelValue':[LabSelection[]]}>();
function toggle(a:LabAlgorithm,checked:boolean){emit('update:modelValue',checked?[...props.modelValue,{id:a.id,parameters:{...a.parameters}}]:props.modelValue.filter(x=>x.id!==a.id));}
function parameter(id:string,key:string,event:Event){const value=Number((event.target as HTMLInputElement).value);emit('update:modelValue',props.modelValue.map(s=>s.id===id?{...s,parameters:{...s.parameters,[key]:value}}:s));}
const labels:Record<string,string>={window:'观察窗口',fast:'短均线',slow:'长均线',multiple:'放量倍数',period:'周期',lower:'低位阈值',upper:'高位阈值',width:'标准差倍数',max_pct:'波动上限(%)',threshold:'涨跌幅阈值(%)'};
function minimum(a:LabAlgorithm){const p=props.modelValue.find(s=>s.id===a.id)?.parameters??a.parameters;const extra=['momentum','volume-breakout'].includes(a.id)?(p.window??0)+1:a.id==='bollinger'?p.window:a.id==='ma-trend'?p.slow:a.id==='atr-risk'?(p.period??0)+1:a.id==='rsi'?(p.period??0)+2:0;return Math.max(a.minimum,extra??0);}
</script>
<template><div class="algorithm-picker" aria-label="选择参与计算的算法"><article v-for="a in catalog.filter(a=>a.supports.includes(mode))" :key="a.id" class="algorithm-option" :class="{selected:modelValue.some(s=>s.id===a.id)}"><label class="algorithm-check"><input type="checkbox" :checked="modelValue.some(s=>s.id===a.id)" @change="toggle(a,($event.target as HTMLInputElement).checked)"><strong>{{a.name}}</strong><span class="tiny muted">{{a.group}}</span></label><p>{{a.description}}</p><span class="tiny muted">{{mode==='daily'?`至少 ${minimum(a)} 根完成日线`:mode==='intraday'?'来源新数据到达时检查':'关联证券公告目录'}} · v{{a.version}}</span><details v-if="modelValue.some(s=>s.id===a.id)&&Object.keys(a.schema).length"><summary>调整参数</summary><div class="algorithm-parameters"><label v-for="(range,key) in a.schema" :key="key">{{labels[key]??key}}<input type="number" :min="range[0]" :max="range[1]" :step="['multiple','width','max_pct','threshold'].includes(String(key))?0.1:1" :value="modelValue.find(s=>s.id===a.id)?.parameters[key]" @change="parameter(a.id,String(key),$event)"></label></div></details></article></div></template>
